// Middleware order -- Authentication MUST precede Authorization
app.UseAuthentication();   // establishes WHO the caller is
app.UseAuthorization();    // checks WHAT they're allowed to do -- depends on the above

// Claims-based identity and policy-based authorization
builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("CanApproveHighValueOrders", policy =>
        policy.RequireClaim("Department", "Finance")
              .RequireClaim("ApprovalLimit"));   // custom requirement, not just a role string
});

[Authorize(Policy = "CanApproveHighValueOrders")]
[HttpPost("approve/{orderId}")]
public async Task<IActionResult> ApproveOrder(int orderId) { /* ... */ }

// Mass assignment / over-posting protection -- bind to a DTO, not the entity directly
public class RegisterUserDto
{
    public string Email { get; set; }
    public string Password { get; set; }
    // Deliberately NO IsAdmin property here -- can't be set via this payload
}

[HttpPost("register")]
public async Task<IActionResult> Register(RegisterUserDto dto)
{
    var user = new User { Email = dto.Email, PasswordHash = Hash(dto.Password) };
    // IsAdmin defaults to false on the entity -- never settable through this endpoint
    await _repo.SaveAsync(user);
    return Ok();
}

// Data Protection shared key ring for multi-instance deployment (prevents random logouts)
builder.Services.AddDataProtection()
    .PersistKeysToStackExchangeRedis(redisConnection, "DataProtection-Keys")
    .SetApplicationName("OrdersApi");   // must match across all instances

// Secrets -- local dev via User Secrets, never in appsettings.json
// dotnet user-secrets set "ConnectionStrings:Default" "Server=...;Password=..."

// Production -- Key Vault as a configuration provider, secret never touches disk/repo
builder.Configuration.AddAzureKeyVault(
    new Uri("https://kv-orders.vault.azure.net"),
    new DefaultAzureCredential());
